const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const center = ee.Geometry.Point([-118.5267, 34.0466]); // Pacific Palisades
  const westPoint = center.translate(-50000, 0); // 50 km west (x offset in meters)
  const swPoint = center.translate(-35355, -35355); // 50 km southwest (x,y offset in meters)
  const regionRadius = 10000; // 10 km radius around each point
  const westRegion = westPoint.buffer(regionRadius);
  const swRegion = swPoint.buffer(regionRadius);

  const date = '2025-01-07';
  const startDate = ee.Date(date);
  const endDate = startDate.advance(1, 'day');

  // 2. Data Acquisition
  const no2Collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .filterDate(startDate, endDate)
    .select('NO2_column_number_density');

  if (no2Collection.size().getInfo() === 0) {
    print('No S5P NO2 data for 2025-01-07.');
    print('<answer>C1</answer>');
    return;
  }

  const no2Image = no2Collection.first();

  // 3. Processing & Validation
  const westStats = no2Image.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: westRegion,
    scale: 1000,
    maxPixels: 1e9
  });
  const swStats = no2Image.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: swRegion,
    scale: 1000,
    maxPixels: 1e9
  });

  const westMean = westStats.get('NO2_column_number_density');
  const swMean = swStats.get('NO2_column_number_density');

  // Pixel count check
  const westCount = no2Image.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: westRegion,
    scale: 1000,
    maxPixels: 1e9
  }).get('NO2_column_number_density');
  const swCount = no2Image.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: swRegion,
    scale: 1000,
    maxPixels: 1e9
  }).get('NO2_column_number_density');

  const westMeanVal = westMean.getInfo();
  const swMeanVal = swMean.getInfo();
  const westCountVal = westCount.getInfo();
  const swCountVal = swCount.getInfo();

  print('West Region - Mean NO2:', westMeanVal, 'Valid pixels:', westCountVal);
  print('SW Region - Mean NO2:', swMeanVal, 'Valid pixels:', swCountVal);

  // 4. Check for valid pixels
  if (westCountVal === 0 || swCountVal === 0) {
    print('One or both regions have 0 valid pixels.');
    print('<answer>C2</answer>');
    return;
  }

  // 5. Check for calculation failures
  if (westMeanVal === null || swMeanVal === null || 
      isNaN(westMeanVal) || isNaN(swMeanVal)) {
    print('Calculation failed (null/NaN).');
    print('<answer>C3</answer>');
    return;
  }

  // 6. Comparison and Final Answer
  if (westMeanVal > swMeanVal) {
    print('<answer>A</answer>');
  } else {
    print('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

